/* Returns the largest reach of the object's collision spheres: the target
 * radius itself for flag 0x20 spheres, otherwise the radius offset by the
 * sphere's height (relative to the object's Y for flag 0x10 spheres). */
f32 func_8019655C(ObjectNode *obj) {
    f32 max = 0.0f;
    s32 i;
    for (i = 0; i < (*(BallCollisionState **)((u8 *)obj + 0xD8))->sphereCount; i++) {
        u8 *state = *(u8 **)((u8 *)obj + 0xD8) + i * sizeof(ObjectCollisionSphere);
        ObjectCollisionSphere *sphere = &((BallCollisionState *)state)->spheres[0];
        u16 flags = sphere->flags;
        f32 reach;
        if (flags & 0x20) {
            reach = sphere->targetRadius;
            if (max < reach) max = reach;
        } else if (flags & 0x10) {
            reach = (*(f32 *)&obj->posY - sphere->center[1]) + sphere->targetRadius;
            if (max < reach) max = reach;
        } else {
            f32 offsetReach = sphere->targetRadius - sphere->center[1];
            if (max < offsetReach) max = offsetReach;
        }
    }
    return max;
}

/* actor_on_ball_impact: react to the ball hitting this actor. Depending on its type
 * the actor is marked with a contact frame, stunned (func_801ADDC4, status timer
 * cleared first) or, for high types, killed (func_80195D50). Most types only react
 * when their model was actually touched. */
